#!/bin/sh
# ==============================================================================
# JunWRT Unified WebUI, PassWall 2, Tailscale & TTL Hotspot Installer
# Target: Arcadyan AW1000 Ultra / MediaTek MT6890 OpenWrt
# Features:
#   1. Cellular Cockpit with Light-White / Dark-Graphite Modem Pages
#   2. Argon Modern Theme & System Branding (root@JunWRT)
#   3. Commercial Cryptographic Licensing Subsystem
#   4. PassWall 2 Modern UI & 1-Click "Add Node via Link" Modal
#   5. Tailscale Mesh VPN Engine:
#      - 1-Click Auth Key Login (tskey-auth-...)
#      - Sub-second non-blocking Web Login URL generation
#      - Normal Go garbage collection with a 128 MiB memory cap (low-memory mode optional)
#      - Native OpenWrt fw3 (iptables) mode with WAN UDP 41641 direct P2P
#   6. TTL hotspot protection for forwarded cellular WAN traffic
# ==============================================================================

trap '' HUP

# Only for the black AW1000 (device tree model AW1000_Ultra): on other MT6890 firmware, such as
# FG360 or seller "Webui_A leon" builds, it would overwrite that firmware's web interface.
JUNWRT_MODEL="$(tr -d '\000' </proc/device-tree/model 2>/dev/null)"
if [ "$JUNWRT_MODEL" != "AW1000_Ultra" ]; then
    echo "[-] STOP: this installer is only for the AW1000 Ultra (black). This router reports: ${JUNWRT_MODEL:-unknown model}" >&2
    exit 1
fi

# Reject concurrent installers before either can replace files or restart services.
mkdir -p /var/run || exit 1
command -v flock >/dev/null 2>&1 || { echo "[-] ERROR: flock is required." >&2; exit 1; }
exec 8>/var/run/junwrt-webui-install.lock || exit 1
flock -n 8 || { echo "[-] ERROR: Another JunWRT WebUI installer is running." >&2; exit 1; }
TMP_TAR="/tmp/junwrt_webui_lic.$$".tar.gz
installer_cleanup() {
    rm -f "$TMP_TAR"
    flock -u 8 2>/dev/null || true
    exec 8>&-
}
trap installer_cleanup EXIT
trap 'exit 1' INT TERM

echo "=================================================================="
echo " [*] Installing JunWRT Unified WebUI, PassWall 2, Tailscale & TTL..."
echo "=================================================================="

# Capture the legacy helper before payload extraction. Its unmarked rules cannot be
# distinguished from owner rules; a fw3 restart rebuilds persistent owner policy.
LEGACY_LICENSE_RULES=0
if [ -f /usr/bin/junwrt-license ] && grep -Fq 'while iptables -D FORWARD -i br-lan -j REJECT' /usr/bin/junwrt-license; then
    LEGACY_LICENSE_RULES=1
fi

# 1. Prepare target directories
mkdir -p /www/luci-static/resources/view/modem
mkdir -p /www/luci-static/resources/view/status/include
mkdir -p /www/luci-static/resources/view/system
mkdir -p /www/luci-static/resources/view/system/filemanager
mkdir -p /usr/share/doc/luci-app-filemanager
mkdir -p /www/luci-static/resources/view/passwall2
mkdir -p /www/luci-static/resources/view
mkdir -p /www/cgi-bin
mkdir -p /www/luci-static/argon/img
mkdir -p /www/luci-static/argon/css
mkdir -p /www/luci-static/resources/icons
mkdir -p /usr/lib/lua/luci/view/themes/argon
mkdir -p /usr/lib/lua/luci/controller
mkdir -p /usr/lib/lua/luci/view/admin_mtk
mkdir -p /usr/lib/lua/luci/view/passwall2/global
mkdir -p /usr/lib/lua/luci/view/passwall2/cbi
mkdir -p /usr/lib/lua/luci/view/passwall2/node_list
mkdir -p /usr/lib/lua/luci/view/passwall2/node_subscribe
mkdir -p /usr/share/luci/menu.d
mkdir -p /usr/share/3ginfo-lite/modem/mtk/fibocom
mkdir -p /usr/share/rpcd/acl.d
mkdir -p /usr/share/rpcd/ucode
mkdir -p /usr/bin
mkdir -p /etc/init.d
mkdir -p /etc/rc.d
mkdir -p /etc/hotplug.d/iface
mkdir -p /etc/tailscale
mkdir -p /usr/share/junwrt-phone
mkdir -p /var/run/tailscale

